import { gunzipSync, strFromU8 } from 'fflate';
// @ts-expect-error - generated by fetch-drawio and bundled with the text loader
import stencilSource from './stencils.generated.txt';

interface StencilBundle {
  files: Record<string, string>;
  namespaces: Record<string, string[]>;
}

interface StencilRegistry {
  dynamicLoading: boolean;
  allowEval: boolean;
  getStencil(name: string): unknown;
  parseStencilSet(root: Element): void;
  loadStencil(filename: string, callback?: (doc: Document | null) => void): Document | null;
}

let bundle: StencilBundle | undefined;
const installed = new WeakSet<StencilRegistry>();

/** Install a per-window lazy registry backed exclusively by bundled data.
 * No vault paths, local server, editor install or network access are needed. */
export function installOfflineStencils(win: Window): void {
  const registry = (win as unknown as { mxStencilRegistry?: StencilRegistry }).mxStencilRegistry;
  if (!registry || installed.has(registry)) return;
  installed.add(registry);
  registry.dynamicLoading = false;
  registry.allowEval = false;
  const original = registry.getStencil.bind(registry);
  const loaded = new Set<string>();
  const read = (path: string): Document | null => {
    bundle ??= JSON.parse(stencilSource as string) as StencilBundle;
    const encoded = Object.prototype.hasOwnProperty.call(bundle.files, path) ? bundle.files[path] : undefined;
    if (!encoded) return null;
    const bytes = Uint8Array.from(win.atob(encoded), (char) => char.charCodeAt(0));
    const Parser = (win as Window & typeof globalThis).DOMParser;
    return new Parser().parseFromString(strFromU8(gunzipSync(bytes)), 'text/xml');
  };
  registry.loadStencil = (filename, callback) => {
    const path = filename.startsWith('drawio-stencils/') ? filename.slice('drawio-stencils/'.length) : '';
    const doc = read(path);
    callback?.(doc);
    return doc;
  };
  registry.getStencil = (name) => {
    let stencil = original(name);
    if (stencil || typeof name !== 'string' || !name.startsWith('mxgraph.')) return stencil;
    bundle ??= JSON.parse(stencilSource as string) as StencilBundle;
    const namespace = name.slice(0, name.lastIndexOf('.'));
    const paths = Object.prototype.hasOwnProperty.call(bundle.namespaces, namespace)
      ? bundle.namespaces[namespace] : undefined;
    for (const path of paths ?? []) {
      if (loaded.has(path)) continue;
      const doc = read(path);
      if (doc) registry.parseStencilSet(doc.documentElement);
      loaded.add(path);
    }
    stencil = original(name);
    return stencil;
  };
}
